1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  [hidden] { display: none !important; }
10	  body {
11	    margin: 0;
12	    min-height: 100vh;
13	    display: flex;
14	    align-items: center;
15	    justify-content: center;
16	    background: #111827;
17	    color: #e5e7eb;
18	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
19	  }
20	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
21	  .board-wrap { position: relative; }
22	  .board {
23	    display: grid;
24	    grid-template-columns: repeat(10, 28px);
25	    grid-template-rows: repeat(20, 28px);
26	    gap: 1px;
27	    padding: 1px;
28	    background: #1f2937;
29	    border: 2px solid #374151;
30	  }
31	  .cell { width: 28px; height: 28px; background-color: #0b1020; }
32	  .mini {
33	    display: grid;
34	    grid-template-columns: repeat(4, 16px);
35	    grid-template-rows: repeat(2, 16px);
36	    gap: 1px;
37	    margin-bottom: 10px;
38	  }
39	  .mini-cell { width: 16px; height: 16px; background-color: transparent; }
40	  .p-I { background-color: #22d3ee; }
41	  .p-O { background-color: #facc15; }
42	  .p-T { background-color: #a855f7; }
43	  .p-S { background-color: #22c55e; }
44	  .p-Z { background-color: #ef4444; }
45	  .p-J { background-color: #3b82f6; }
46	  .p-L { background-color: #f97316; }
47	  .panel { width: 160px; }
48	  .stat { margin-bottom: 14px; }
49	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9ca3af; }
50	  .stat .value { font-size: 24px; font-weight: 600; font-variant-numeric: tabular-nums; }
51	  .help { font-size: 12px; color: #9ca3af; line-height: 1.6; margin-top: 12px; }
52	  .overlay {
53	    position: absolute;
54	    inset: 0;
55	    display: flex;
56	    flex-direction: column;
57	    align-items: center;
58	    justify-content: center;
59	    background: rgba(17, 24, 39, 0.8);
60	    font-size: 22px;
61	    font-weight: 600;
62	  }
63	  .overlay small { font-size: 13px; font-weight: 400; margin-top: 8px; color: #d1d5db; }
64	</style>
65	</head>
66	<body>
67	<div class="game">
68	  <div class="board-wrap">
69	    <div class="board" id="board" data-testid="board"></div>
70	    <div class="overlay" id="overlay" data-testid="game-over" hidden>Game over<small>Press Enter to play again</small></div>
71	  </div>
72	  <div class="panel">
73	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
74	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
75	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
76	    <div class="stat"><div class="label">Next</div><div id="next" data-testid="next-piece"></div></div>
77	    <div class="help">
78	      ← → move<br>
79	      ↑ rotate<br>
80	      ↓ soft drop<br>
81	      Space hard drop<br>
82	      Enter new game
83	    </div>
84	  </div>
85	</div>
86	<script>
87	(function () {
88	  "use strict";
89	
90	  var ROWS = 20;
91	  var COLS = 10;
92	  var PREVIEW = 3;
93	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
94	
95	  // Spawn orientation of each piece inside its rotation box.
96	  var SHAPES = {
97	    I: ["....", "IIII", "....", "...."],
98	    O: ["OO", "OO"],
99	    T: [".T.", "TTT", "..."],
100	    S: [".SS", "SS.", "..."],
101	    Z: ["ZZ.", ".ZZ", "..."],
102	    J: ["J..", "JJJ", "..."],
103	    L: ["..L", "LLL", "..."]
104	  };
105	
106	  // Scoring (decision): points for rows cleared at once, times level. Clearing rows
107	  // together always beats clearing them one at a time. Soft drop 1 per cell, hard drop 2.
108	  var LINE_POINTS = [0, 100, 300, 500, 800];
109	  var SOFT_DROP_POINTS = 1;
110	  var HARD_DROP_POINTS = 2;
111	
112	  var state = {
113	    board: [],      // ROWS arrays of COLS chars: "." or a piece letter
114	    current: null,  // { type, matrix, row, col }
115	    next: [],
116	    bag: [],
117	    score: 0,
118	    level: 1,
119	    lines: 0,
120	    status: "running"
121	  };
122	
123	  var timer = null;
124	
125	  // ---------- pieces ----------
126	
127	  function isType(t) { return TYPES.indexOf(t) !== -1; }
128	
129	  function randomType() {
130	    if (state.bag.length === 0) {
131	      var bag = TYPES.slice();
132	      for (var i = bag.length - 1; i > 0; i--) {
133	        var j = Math.floor(Math.random() * (i + 1));
134	        var tmp = bag[i]; bag[i] = bag[j]; bag[j] = tmp;
135	      }
136	      state.bag = bag;
137	    }
138	    return state.bag.pop();
139	  }
140	
141	  function cleanQueue(queue) {
142	    if (!Array.isArray(queue)) return [];
143	    return queue.map(function (t) { return String(t).toUpperCase(); }).filter(isType);
144	  }
145	
146	  function fillPreview() {
147	    while (state.next.length < PREVIEW) state.next.push(randomType());
148	  }
149	
150	  function makeMatrix(type) {
151	    return SHAPES[type].map(function (r) { return r.split(""); });
152	  }
153	
154	  function pieceCells(piece) {
155	    var cells = [];
156	    for (var r = 0; r < piece.matrix.length; r++) {
157	      for (var c = 0; c < piece.matrix[r].length; c++) {
158	        if (piece.matrix[r][c] !== ".") cells.push([piece.row + r, piece.col + c]);
159	      }
160	    }
161	    return cells;
162	  }
163	
164	  function fits(matrix, row, col) {
165	    for (var r = 0; r < matrix.length; r++) {
166	      for (var c = 0; c < matrix[r].length; c++) {
167	        if (matrix[r][c] === ".") continue;
168	        var br = row + r, bc = col + c;
169	        if (br < 0 || br >= ROWS || bc < 0 || bc >= COLS) return false;
170	        if (state.board[br][bc] !== ".") return false;
171	      }
172	    }
173	    return true;
174	  }
175	
176	  // [REQ-001] [REQ-004] Spawn the next piece; the game ends if it has nowhere to go.
177	  function spawn() {
178	    var type = state.next.length ? state.next.shift() : randomType();
179	    fillPreview();
180	    var matrix = makeMatrix(type);
181	    var top = 0;
182	    while (matrix[top].every(function (ch) { return ch === "."; })) top++;
183	    var piece = {
184	      type: type,
185	      matrix: matrix,
186	      row: -top,
187	      col: Math.floor((COLS - matrix[0].length) / 2),
188	      lockTicks: 0,
189	      lockResets: 0
190	    };
191	    if (!fits(piece.matrix, piece.row, piece.col)) {
192	      state.current = null;
193	      state.status = "gameover";
194	      stopTimer();
195	      return;
196	    }
197	    state.current = piece;
198	  }
199	
200	  // ---------- core rules ----------
201	
202	  // [REQ-003] Remove full rows, drop the rest, score by rows cleared at once times level.
203	  function clearLines() {
204	    var kept = state.board.filter(function (row) {
205	      return row.some(function (ch) { return ch === "."; });
206	    });
207	    var cleared = ROWS - kept.length;
208	    while (kept.length < ROWS) kept.unshift(emptyRow());
209	    state.board = kept;
210	    if (cleared > 0) {
211	      state.score += LINE_POINTS[cleared] * state.level;
212	      state.lines += cleared;
213	      state.level = Math.floor(state.lines / 10) + 1;
214	    }
215	  }
216	
217	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next one.
218	  function lockPiece() {
219	    var p = state.current;
220	    pieceCells(p).forEach(function (cell) {
221	      state.board[cell[0]][cell[1]] = p.type;
222	    });
223	    state.current = null;
224	    clearLines();
225	    spawn();
226	  }
227	
228	  function tryMove(dr, dc) {
229	    var p = state.current;
230	    if (!p || !fits(p.matrix, p.row + dr, p.col + dc)) return false;
231	    p.row += dr;
232	    p.col += dc;
233	    return true;
234	  }
235	
236	  // Lock rule (DEC): a gravity step that cannot move the piece down counts one tick of
237	  // lock delay; the piece locks on the LOCK_DELAY-th such tick. A left/right move while
238	  // resting restarts the delay, at most MAX_LOCK_RESETS times per piece. A soft drop on a
239	  // resting piece restarts it too, from the same budget.
240	  var LOCK_DELAY = 2;
241	  var MAX_LOCK_RESETS = 3;
242	
243	  function isResting(p) {
244	    return !fits(p.matrix, p.row + 1, p.col);
245	  }
246	
247	  // [REQ-002] [REQ-005] Restart the lock delay if the piece has restarts left.
248	  function restartLockDelay(p) {
249	    if (p.lockResets < MAX_LOCK_RESETS) {
250	      p.lockResets++;
251	      p.lockTicks = 0;
252	    }
253	  }
254	
255	  // [REQ-002] One gravity step: fall one row, or count a tick of lock delay.
256	  // Used by the real timer, by tick(n) and by soft drop. Returns true if the piece fell.
257	  function gravityStep() {
258	    if (state.status !== "running" || !state.current) return false;
259	    var p = state.current;
260	    if (tryMove(1, 0)) {
261	      p.lockTicks = 0;
262	      return true;
263	    }
264	    p.lockTicks++;
265	    if (p.lockTicks >= LOCK_DELAY) lockPiece();
266	    return false;
267	  }
268	
269	  // [REQ-002] Sideways move; restarts the lock delay if the piece was resting.
270	  function shift(dc) {
271	    var p = state.current;
272	    var resting = isResting(p);
273	    if (!tryMove(0, dc)) return;
274	    if (resting) restartLockDelay(p);
275	  }
276	
277	  // [REQ-003] [REQ-005] Soft drop: fall one row for a point. On a resting piece it scores
278	  // nothing and restarts the lock delay like a sideways move, instead of counting a tick.
279	  function softDrop() {
280	    var p = state.current;
281	    if (isResting(p)) {
282	      restartLockDelay(p);
283	      return;
284	    }
285	    tryMove(1, 0);
286	    p.lockTicks = 0;
287	    state.score += SOFT_DROP_POINTS;
288	  }
289	
290	  // [REQ-002] Clockwise rotation with sideways kicks; refused if nothing fits.
291	  function rotate() {
292	    var p = state.current;
293	    if (!p) return;
294	    var size = p.matrix.length;
295	    var rotated = [];
296	    for (var r = 0; r < size; r++) {
297	      rotated.push([]);
298	      for (var c = 0; c < size; c++) rotated[r].push(p.matrix[size - 1 - c][r]);
299	    }
300	    var kicks = [0, -1, 1, -2, 2];
301	    for (var i = 0; i < kicks.length; i++) {
302	      if (fits(rotated, p.row, p.col + kicks[i])) {
303	        p.matrix = rotated;
304	        p.col += kicks[i];
305	        return;
306	      }
307	    }
308	  }
309	
310	  // [REQ-001] [REQ-003] Player actions; soft and hard drop score per cell moved down.
311	  function input(action) {
312	    if (state.status !== "running" || !state.current) return;
313	    switch (action) {
314	      case "left": shift(-1); break;
315	      case "right": shift(1); break;
316	      case "softDrop": softDrop(); break;
317	      case "hardDrop":
318	        var dropped = 0;
319	        while (tryMove(1, 0)) dropped++;
320	        state.score += dropped * HARD_DROP_POINTS;
321	        lockPiece();
322	        break;
323	      case "rotate":
324	      case "rotateCW": rotate(); break;
325	      default: return;
326	    }
327	    render();
328	    restartTimerIfNeeded();
329	  }
330	
331	  // ---------- timer ----------
332	
333	  function gravityInterval() {
334	    return Math.max(100, 1000 - (state.level - 1) * 90);
335	  }
336	
337	  function stopTimer() {
338	    if (timer !== null) { clearTimeout(timer); timer = null; }
339	  }
340	
341	  function startTimer() {
342	    stopTimer();
343	    if (state.status !== "running") return;
344	    timer = setTimeout(function () {
345	      timer = null;
346	      gravityStep();
347	      render();
348	      startTimer();
349	    }, gravityInterval());
350	  }
351	
352	  function restartTimerIfNeeded() {
353	    if (state.status === "running" && timer === null) startTimer();
354	  }
355	
356	  // ---------- setup ----------
357	
358	  function emptyRow() {
359	    var row = [];
360	    for (var c = 0; c < COLS; c++) row.push(".");
361	    return row;
362	  }
363	
364	  // [REQ-001] Start a fresh game, optionally with a fixed piece order.
365	  function newGame(queue) {
366	    state.board = [];
367	    for (var r = 0; r < ROWS; r++) state.board.push(emptyRow());
368	    state.bag = [];
369	    state.score = 0;
370	    state.level = 1;
371	    state.lines = 0;
372	    state.status = "running";
373	    state.current = null;
374	    state.next = cleanQueue(queue);
375	    fillPreview();
376	    spawn();
377	    render();
378	    startTimer();
379	  }
380	
381	  // ---------- rendering (synchronous) ----------
382	
383	  var boardEl = document.getElementById("board");
384	  var nextEl = document.getElementById("next");
385	  var scoreEl = document.getElementById("score");
386	  var levelEl = document.getElementById("level");
387	  var linesEl = document.getElementById("lines");
388	  var overlayEl = document.getElementById("overlay");
389	  var cellEls = [];
390	
391	  (function buildBoard() {
392	    for (var r = 0; r < ROWS; r++) {
393	      cellEls.push([]);
394	      for (var c = 0; c < COLS; c++) {
395	        var el = document.createElement("div");
396	        el.className = "cell";
397	        el.setAttribute("data-testid", "cell");
398	        el.setAttribute("data-row", String(r));
399	        el.setAttribute("data-col", String(c));
400	        el.setAttribute("data-filled", "false");
401	        el.setAttribute("data-piece", "");
402	        boardEl.appendChild(el);
403	        cellEls[r].push(el);
404	      }
405	    }
406	  })();
407	
408	  function paintCell(el, type) {
409	    el.className = type ? "cell p-" + type : "cell";
410	    el.setAttribute("data-filled", type ? "true" : "false");
411	    el.setAttribute("data-piece", type || "");
412	  }
413	
414	  // [REQ-004] Next three pieces, soonest first, coloured as on the board.
415	  function renderPreview() {
416	    nextEl.textContent = "";
417	    state.next.slice(0, PREVIEW).forEach(function (type) {
418	      var grid = document.createElement("div");
419	      grid.className = "mini";
420	      grid.setAttribute("data-testid", "next-piece-item");
421	      grid.setAttribute("data-piece", type);
422	      var rows = SHAPES[type].filter(function (r) { return r.indexOf(type) !== -1; });
423	      for (var r = 0; r < 2; r++) {
424	        for (var c = 0; c < 4; c++) {
425	          var cell = document.createElement("div");
426	          var ch = rows[r] ? rows[r].charAt(c) : ".";
427	          cell.className = ch === type ? "mini-cell p-" + type : "mini-cell";
428	          grid.appendChild(cell);
429	        }
430	      }
431	      nextEl.appendChild(grid);
432	    });
433	  }
434	
435	  // [REQ-001] Draw the whole game state into the DOM, immediately.
436	  function render() {
437	    var drawn = state.board.map(function (row) { return row.slice(); });
438	    if (state.current) {
439	      var type = state.current.type;
440	      pieceCells(state.current).forEach(function (cell) {
441	        drawn[cell[0]][cell[1]] = type;
442	      });
443	    }
444	    for (var r = 0; r < ROWS; r++) {
445	      for (var c = 0; c < COLS; c++) {
446	        var ch = drawn[r][c];
447	        paintCell(cellEls[r][c], ch === "." ? "" : ch);
448	      }
449	    }
450	    scoreEl.textContent = String(state.score);
451	    levelEl.textContent = String(state.level);
452	    linesEl.textContent = String(state.lines);
453	    overlayEl.hidden = state.status !== "gameover";
454	    renderPreview();
455	  }
456	
457	  // ---------- keyboard ----------
458	
459	  document.addEventListener("keydown", function (e) {
460	    var map = {
461	      ArrowLeft: "left",
462	      ArrowRight: "right",
463	      ArrowDown: "softDrop",
464	      ArrowUp: "rotateCW",
465	      " ": "hardDrop"
466	    };
467	    if (e.key === "Enter") {
468	      e.preventDefault();
469	      newGame();
470	      return;
471	    }
472	    if (map[e.key]) {
473	      e.preventDefault();
474	      input(map[e.key]);
475	    }
476	  });
477	
478	  // ---------- test control surface ----------
479	
480	  // [REQ-001]
481	  window.__tetris = {
482	    newGame: function (queue) { newGame(queue); },
483	    setQueue: function (queue) {
484	      state.next = cleanQueue(queue);
485	      fillPreview();
486	      render();
487	    },
488	    setBoard: function (rows) {
489	      var board = [];
490	      for (var r = 0; r < ROWS; r++) {
491	        var line = rows && typeof rows[r] === "string" ? rows[r] : "";
492	        var row = [];
493	        for (var c = 0; c < COLS; c++) {
494	          var ch = line.charAt(c);
495	          row.push(isType(ch) ? ch : ".");
496	        }
497	        board.push(row);
498	      }
499	      state.board = board;
500	      render();
501	    },
502	    tick: function (n) {
503	      var steps = n === undefined ? 1 : n;
504	      for (var i = 0; i < steps; i++) gravityStep();
505	      render();
506	    },
507	    input: function (action) { input(action); },
508	    getBoard: function () {
509	      return state.board.map(function (row) { return row.join(""); });
510	    },
511	    getState: function () {
512	      return {
513	        current: state.current
514	          ? { type: state.current.type, cells: pieceCells(state.current) }
515	          : null,
516	        next: state.next.slice(),
517	        score: state.score,
518	        level: state.level,
519	        lines: state.lines,
520	        status: state.status
521	      };
522	    }
523	  };
524	
525	  newGame();
526	})();
527	</script>
528	</body>
529	</html>
